import{_ as l,l as r,o as t,c as s,v as e,p as h,x as i,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"化学随机性抑制","description":"","frontmatter":{"title":"化学随机性抑制","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/chemical-stochastic-mitigation.md","filePath":"litho/chemical-stochastic-mitigation.md","lastUpdated":1789023840000}'),d={name:"litho/chemical-stochastic-mitigation.md"};function E(A,a,m,_,B,P){const o=r("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="化学随机性抑制" tabindex="-1">化学随机性抑制 <a class="header-anchor" href="#化学随机性抑制" aria-label="Permalink to &quot;化学随机性抑制&quot;">​</a></h1><div class="epigraph"><p>光学把 NILS 做高、剂量把 $N$ 做大之后，剩下的地板在分子能不能均匀、事件能不能多而不糊。化学抑制是在 RLS 三角里改材料边，不是另发明一种泊松。</p><footer>—— 据 Naulleau / 配方公开叙述对加载、均匀分散与淬灭的讨论；Ito 增益的代价见 CAR 课</footer></div><p><a href="/litho/stochastic-process-window">上一课</a>把量产点放在随机窗里。缺口是胶配方还能做什么：在不大改镜头的前提下把悬崖推开。本课钉化学抑制。金属氧化物另一套机制，留给<a href="/litho/mor-stochastics">下一课</a>。干法显影再下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>化学杠杆已经在课序里散落：加 PAG 密度提高事件数；加淬灭缩短核、压暗区；降 PEB 缩 \\(\\ell\\)；提高吸收（氟化、金属）提高单位剂量的 \\(N\\)；改善分散减少团聚低频；光可分解淬灭剂让亮区碱消失、暗区仍在。每一项都挪 RLS 的点。缺口是把它们写成「随机窗执行器清单」，而不是再定义淬灭剂。</p><p>禁止项：用更高化学增益（酸放大器、过长 PEB）去买灵敏度，通常把出生噪声放大，随机窗变窄。Ito 的增益在光子充裕的 DUV 是产能工具；在 EUV 计数受限区要记账。</p><h3 id="均匀比「平均加载高」更硬" tabindex="-1">均匀比「平均加载高」更硬 <a class="header-anchor" href="#均匀比「平均加载高」更硬" aria-label="Permalink to &quot;均匀比「平均加载高」更硬&quot;">​</a></h3><p>平均 PAG wt% 高但团聚，有效体积里仍有空斑，低频 LER 与缺孔地板不掉。分散、相容的聚合物–PAG、避免结晶，是化学抑制里最不像「灵敏度广告」的一项。计量要用谱的低频，不只 \\(E_0\\)。</p><p><span class="marginnote">环境胺与延迟 PEB 是负向化学：顶部额外淬灭，T-top 加局部阈值噪声。抑制包括轨道卫生，不单是配方。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照矩阵（固定光学）：扫负载、PAG 种类、PEB、\\(B\\) 吸收，同时报 \\(E_\\mathrm{size}\\)、PSD、缺陷率。成功的抑制：缺陷悬崖外移，而半节距仍可分辩。失败的「抑制」：LER \\(3\\sigma\\) 降了（核糊了），缺陷地板不降或分辨率死。与<a href="/litho/quencher-loading">淬灭剂负载</a>同一条浓度轴，本课只读随机窗那一列。</p><p>底层：提高界面电子均匀性、减少底部空斑，属于化学/栈抑制，黏附课的剥落不在此列。</p>',12)),(t(),h(p,null,{default:i(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAG%5B%22PAG%20%E5%AF%86%E5%BA%A6%E4%B8%8E%E5%88%86%E6%95%A3%22%5D%20--%3E%20WIN%5B%22%E9%9A%8F%E6%9C%BA%E7%AA%97%22%5D%0A%20%20Q%5B%22%E6%B7%AC%E7%81%AD%20%2F%20PDQ%22%5D%20--%3E%20WIN%0A%20%20ABS%5B%22%E5%90%B8%E6%94%B6%E6%88%AA%E9%9D%A2%22%5D%20--%3E%20WIN%0A%20%20PEB%5B%22PEB%20%2F%20%E2%84%93%22%5D%20--%3E%20WIN%0A%20%20GAIN%5B%22%E8%BF%87%E9%AB%98%E5%8C%96%E5%AD%A6%E5%A2%9E%E7%9B%8A%22%5D%20--%3E%20TAIL%5B%22%E5%B0%BE%E6%9B%B4%E8%82%A5%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>事件密度升，相对泊松降，前提是事件在空间上不簇成一团。核缩短，有效体积降，相对涨落升，但 NILS 潜像升——净效果看哪一项主导，必须测，不能从三角口号推断符号。高吸收把光子停在更薄的膜里，\\(N\\) 够、倒塌预算也够，这是 High-NA 薄膜的正道；吸收团簇化则引入新的散粒。</p><p>光可分解淬灭剂：亮区 \\(q\\) 下降，灵敏度回升，暗区 \\(q\\) 仍压桥。随机上，亮区碱计数变少，断线侧可能变差，桥侧变好——两座悬崖不对称移动，要两张缺陷曲线。</p><p><span class="marginnote">换显影液 / Notch 陡度会改噪声增益，类似 \\(\\gamma\\) 过大。那是显影化学，也属本课清单，但流体力学仍留给轨道课。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写分子式与 wt% 表。不把某供应商「低随机胶」宣传当定律。下一课 MOR：抑制策略从 PAG 计数换成团簇与配体，本课 CAR 清单不能复印。干法显影改的是溶解噪声那一截。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>化学抑制：加载、分散、吸收、淬灭/PDQ、PEB，每项都挪 RLS。</li><li>用缺陷悬崖与谱检验，不要只用 \\(E_0\\) 或 \\(3\\sigma\\)。</li><li>过高化学增益常伤随机窗；团聚造成剂量压不掉的地板。</li><li>PDQ 让两座悬崖不对称移动。</li><li>出处：Naulleau；<a href="/litho/pag-quencher">PAG 与淬灭剂</a>；Mack 配方与 PEB。</li></ul>',8))])}const N=l(d,[["render",E]]);export{f as __pageData,N as default};
